WITH employees_by_department AS (SELECT dept_id, ROUND(STDDEV(salary), 2) AS stddev_salary, COUNT(DISTINCT salary) AS unique_depts FROM employees GROUP BY dept_id) SELECT d.id, d.location, ebd.stddev_salary, ebd.unique_depts FROM departments d LEFT JOIN employees_by_department ebd ON d.id = ebd.dept_id WHERE ebd.stddev_salary >= 47;
